ode at (3,2) {$\mu^*$}; \end{tikzpicture} \caption{} \end{subfigure} \hspace{1cm}  egin{subfigure}[b]{0.4	extwidth} \centering  egin{tikzpicture}[xscale=1, yscale=1] \draw [thick, ->] (0.5,0.5) -- (0.5, 3.5); 
ode at (0,3) {$\log Z$}; \draw [thick, ->] (0.5,0.5) -- (4.5, 0.5); 
